/**
 * @brief Extracts the domain name from a QUIC packet.
 *
 * This function processes a QUIC packet to extract the domain name by performing the following steps:
 * 1. Parses the Destination Connection ID (DCID) from the packet.
 * 2. Derives initial keys using the DCID.
 * 3. Unmasks the packet header.
 * 4. Generates a nonce for AEAD decryption.
 * 5. Decrypts the protected packet payload.
 * 6. Parses the TLS record to find the beginning of extensions.
 * 7. Extracts the domain name from the TLS extensions.
 *
 * @param packet Pointer to the QUIC packet.
 * @param packet_len Length of the QUIC packet.
 * @param isClient Boolean indicating if the packet is from a client.
 * @param keys Pointer to the structure containing QUIC cryptographic keys.
 * @return char* Pointer to the extracted domain name. The caller is responsible for freeing the allocated memory.
 */
char *getDomain(const uint8_t* packet, int packet_len, bool isClient, QuicCryptoKeys* keys) {
    //DCID PARSER =======================================================================================
    // printf("Received QUIC packet of length %d\n", packet_len);
    // printf("Packet: ");
    // for (int i = 0; i < packet_len; i++) {
    //     printf("%02x", packet[i]);
    // }
    uint8_t dcid_length;
    uint8_t* dcid_ptr = get_dcid(packet, isClient, &dcid_length);
    // printf("\nDCID: "); 
    // for (int i = 0; i < dcid_length; i++) {
    //     printf("%02x", dcid_ptr[i]);
    // }
    //KEY DERIVATION ====================================================================================
    derive_initial_keys(dcid_ptr,dcid_length, isClient, keys);
    // printf("\nDerived Keys in getDOmain: ");
    // for (int i = 0; i < 16; i++) {
    //     printf("%02x", keys->quic_key[i]);
    // }

    //HEADER UNMASK ======================================================================================
    uint8_t* demasked_header = NULL;
    size_t demasked_header_len = 0;
    header_unmask(packet, packet_len, keys->quic_hp, &demasked_header, &demasked_header_len);
    // printf("\nDemasked Header: ");
    // for (size_t i = 0; i < demasked_header_len; i++) {
    //     printf("%02x", demasked_header[i]);
    // }
    // printf("\n");
    // TESTING GROUND ==============================================================================================================================
    //header_mask(icloud_frame_sample, keys->quic_hp, demasked_header, demasked_header_len, &remasked_header);
    // TESTING GROUND ==============================================================================================================================


    //NONCE GENERATION ==========================================================================================
    u_int8_t nonce[12];
    generate_aead_nonce(keys->quic_iv, sizeof(keys->quic_iv), pn(demasked_header,pn_length(demasked_header), demasked_header_len), nonce);

    //AEAD DECRYPTION ==========================================================================================
    uint8_t* protected_packet = packet + demasked_header_len;
    size_t decrypted_packet_len = packet_len - demasked_header_len - 16;
    uint8_t *decrypted_packet = malloc(decrypted_packet_len);
    if (!decrypted_packet) {
        perror("Failed to allocate memory for decrypt packet");
        exit(EXIT_FAILURE);
    }
    int ret = aead_decrypt(keys->quic_key, sizeof(keys->quic_key), nonce, sizeof(nonce), demasked_header, demasked_header_len, protected_packet, packet_len - demasked_header_len, decrypted_packet);

    // printf("\n");
    //reverse encryption
    //int ret2 = aead_encrypt(keys->quic_key, sizeof(keys->quic_key), nonce, sizeof(nonce), demasked_header, demasked_header_len, decrypted_packet, decrypted_packet_len, reverse_protected);



    //TLS RECORD PARSER (find the beginning of extensions) =================================================================
    if (ret == -1){
        return NULL;

    }
    uint8_t *tls_payload = decrypted_packet + 4;
    int offset_value = 38;  //Starting byte of the first variable length parameters
    int session_id_len = tls_payload[offset_value];
    offset_value += session_id_len;
    offset_value+=2; //Ciphersuite length
    int cipher_suite_len = (tls_payload[offset_value-1] << 8) | tls_payload[offset_value];
    offset_value += cipher_suite_len;
    offset_value++;//compression method len
    int compression_method_len = tls_payload[offset_value];
    offset_value += compression_method_len;
    offset_value +=2; //extension length
    int counter = 1+offset_value; // The start of TLS extensios
	char extractedName[256]; // Assuming a maximum name length of 256 characters
	int nameIndex = 0;		 // Index for the extractedName array
    
    // TLS EXTENSION PARSER ==========================================================================================
    while (1)
	{
		uint16_t type = (uint16_t)tls_payload[counter] << 8 | (uint16_t)tls_payload[counter + 1];
        //printf("type: %d\n", type);
		if (type == 0)
		{
			uint16_t namelength = (uint16_t)tls_payload[counter + 2] << 8 | (uint16_t)tls_payload[counter + 3];
            //printf("\nName Length: %d\n", namelength);
			for (int i = 0; i < namelength; i++)
			{
				extractedName[nameIndex] = (char)tls_payload[counter + 9 + i];
				nameIndex++;
			}
			extractedName[nameIndex] = '\0';

			// Dynamically allocate memory for the string to return
            char *result = (char *)malloc(strlen(extractedName) + 1);
            strcpy(result, extractedName);
            free(decrypted_packet);    
            free(demasked_header);  
            // printf("\nExtracted Name: %s\n", result);  
            return result;
		}
		else
		{
			uint16_t length = (uint16_t)tls_payload[counter + 2] << 8 | (uint16_t)tls_payload[counter + 3];
			counter += length + 4;
		}
	}
    free(decrypted_packet);    
    free(demasked_header);    
    return NULL;
}

void quic_payload_crafter(const uint8_t* scid, uint8_t scid_len,
    const uint8_t* dcid, uint8_t dcid_len,
    uint8_t* output, uint32_t* output_len, QuicCryptoKeys* keys, bool to_server) {
    uint8_t header[100];  // Sufficient space for QUIC connection close
    uint8_t frame[100]; // Sufficient space for QUIC Initial packet
    uint32_t hdr_offset = 0, frame_offset = 0;
    // printf("=======================================QUIC Payload Crafter - to_server = %d ==================================\n", to_server);
    // // Debug prints for connection IDs
    // printf("DCID Length: %d\nDCID: ", dcid_len);
    // for (int i = 0; i < dcid_len; i++) printf("%02x", dcid[i]);
    // printf("\nSCID Length: %d\nSCID: ", scid_len);
    // for (int i = 0; i < scid_len; i++) printf("%02x", scid[i]);
    // printf("\n");


    // 1. First create the CONNECTION_CLOSE frame (transport error, type 0x1c)
    const char* reason = "BLOCKED_BY_POLICY_SERVER";
    uint32_t reason_len = strlen(reason);
    uint32_t error_code = 0x02; // INTERNAL_ERROR
    uint32_t frame_type = 0x06; // CRYPTO FRAME triggered the error

    // Frame type
    
    frame[frame_offset++] = 0x1c; // CONNECTION_CLOSE (transport error)

    // Error Code (variable-length integer)
    if (error_code < 64) {
        frame[frame_offset++] = error_code;
    } else if (error_code < 16384) {
        frame[frame_offset++] = 0x40 | (error_code >> 8);
        frame[frame_offset++] = error_code & 0xFF;
    } else {
        frame[frame_offset++] = 0x80 | (error_code >> 24);
        frame[frame_offset++] = (error_code >> 16) & 0xFF;
        frame[frame_offset++] = (error_code >> 8) & 0xFF;
        frame[frame_offset++] = error_code & 0xFF;
    }

    // Frame Type that triggered error (variable-length integer)
    if (frame_type < 64) {
        frame[frame_offset++] = frame_type;
    } else if (frame_type < 16384) {
        frame[frame_offset++] = 0x40 | (frame_type >> 8);
        frame[frame_offset++] = frame_type & 0xFF;
    } else {
        frame[frame_offset++] = 0x80 | (frame_type >> 24);
        frame[frame_offset++] = (frame_type >> 16) & 0xFF;
        frame[frame_offset++] = (frame_type >> 8) & 0xFF;
        frame[frame_offset++] = frame_type & 0xFF;
    }

    // Reason Phrase Length (variable-length integer)
    if (reason_len < 64) {
        frame[frame_offset++] = reason_len;
    } else if (reason_len < 16384) {
        frame[frame_offset++] = 0x40 | (reason_len >> 8);
        frame[frame_offset++] = reason_len & 0xFF;
    } else {
        frame[frame_offset++] = 0x80 | (reason_len >> 24);
        frame[frame_offset++] = (reason_len >> 16) & 0xFF;
        frame[frame_offset++] = (reason_len >> 8) & 0xFF;
        frame[frame_offset++] = reason_len & 0xFF;
    }

    // Reason Phrase
    memcpy(&frame[frame_offset], reason, reason_len);
    frame_offset += reason_len;

    // 2. Now create the QUIC header
    header[hdr_offset++] = 0b11000000;  // Long header with Initial type

    // QUIC Version (4 bytes, big-endian)
    for (int i = 24; i >= 0; i -= 8) {
        header[hdr_offset++] = (QUIC_VERSION >> i) & 0xFF;
    }

    // Connection IDs
    if(!to_server){
        header[hdr_offset++] = scid_len;
        memcpy(&header[hdr_offset], scid, scid_len);
        hdr_offset += scid_len;

        uint8_t new_dcid []= {0xfd, 0x8b, 0x4b, 0xf2}; 
        // printf("\nNew DCID size: %zu\n", sizeof(new_dcid));
        header[hdr_offset++] = sizeof(new_dcid);
        memcpy(&header[hdr_offset], new_dcid, sizeof(new_dcid));
        hdr_offset += sizeof(new_dcid);
    } else{
        header[hdr_offset++] = dcid_len;
        memcpy(&header[hdr_offset], dcid, dcid_len);
        hdr_offset += dcid_len;

        header[hdr_offset++] = scid_len;
        memcpy(&header[hdr_offset], scid, scid_len);
        hdr_offset += scid_len;
    }


    // Token Length (variable-length integer, zero in this case)
    header[hdr_offset++] = 0x00;  // Zero-length token (1-byte encoding)

    // Length Field (variable-length integer) - reserve max space (4 bytes)
    uint32_t hdr_length_offset = hdr_offset;
    hdr_offset += 4;  // Temporarily reserve maximum space

    // Packet number
    header[hdr_offset++] = 0x00;  // Packet number

    // Calculate total payload length (frame + AEAD overhead)
    uint32_t payload_length = frame_offset+16+1; // 16 bytes for AEAD tag
    uint32_t length_bytes_needed;

    // Encode payload length as variable-length integer
    if (payload_length < 64) {
        length_bytes_needed = 1;
        header[hdr_length_offset] = payload_length & 0x3F;
    } else if (payload_length < 16384) {
        length_bytes_needed = 2;
        header[hdr_length_offset] = 0x40 | ((payload_length >> 8) & 0x3F);
        header[hdr_length_offset + 1] = payload_length & 0xFF;
    } else {
        length_bytes_needed = 4;
        header[hdr_length_offset] = 0x80 | ((payload_length >> 24) & 0x3F);
        header[hdr_length_offset + 1] = (payload_length >> 16) & 0xFF;
        header[hdr_length_offset + 2] = (payload_length >> 8) & 0xFF;
        header[hdr_length_offset + 3] = payload_length & 0xFF;
    }

    // Shift header content if we used fewer bytes than reserved
    if (length_bytes_needed < 4) {
        uint32_t shift = 4 - length_bytes_needed;
        memmove(&header[hdr_length_offset + length_bytes_needed],
                &header[hdr_length_offset + 4],
                hdr_offset - (hdr_length_offset + 4));
        hdr_offset -= shift;
    }

    // // Debug prints - C array format
    // printf("uint8_t header[%d] = {", hdr_offset);
    // for (int i = 0; i < hdr_offset; i++) {
    //     printf("0x%02x", header[i]);
    //     if (i < hdr_offset - 1) printf(", ");
    // }
    // printf("};\n");

    // printf("uint8_t frame[%d] = {", frame_offset);
    // for (int i = 0; i < frame_offset; i++) {
    //     printf("0x%02x", frame[i]);
    //     if (i < frame_offset - 1) printf(", ");
    // }
    // printf("};\n\n");
    
    uint8_t *encrypted_frame = malloc(payload_length-1);
    //NONCE GENERATION ==========================================================================================
    u_int8_t nonce[12];
    if (to_server){
        generate_aead_nonce(keys->quic_iv, sizeof(keys->quic_iv), pn(header,pn_length(header), hdr_offset), nonce);}
    else{
        generate_aead_nonce(keys->quic_iv_server, sizeof(keys->quic_iv_server), pn(header,pn_length(header), hdr_offset), nonce);}
    // printf("===== AEAD Encryption Parameters =====\n");
    // // Print server key
    // printf("Server Key (%zu bytes):\n", sizeof(keys->quic_key_server));
    // for (size_t i = 0; i < sizeof(keys->quic_key_server); i++) {
    //     printf("%02x", keys->quic_key_server[i]);
    //     if ((i + 1) % 16 == 0) printf("\n");
    //     else if ((i + 1) % 4 == 0) printf(" ");
    // }
    // printf("\n\n");
    
    // // Print nonce
    // printf("Nonce (%zu bytes):\n", sizeof(nonce));
    // for (size_t i = 0; i < sizeof(nonce); i++) {
    //     printf("%02x", nonce[i]);
    //     if ((i + 1) % 4 == 0) printf(" ");
    // }
    // printf("\n\n");
    // //print header
    // printf("header (%zu bytes):\n", hdr_offset);
    // for (size_t i = 0; i < hdr_offset; i++) {
    //     printf("%02x", header[i]);
    //     if ((i + 1) % 4 == 0) printf(" ");
    // }
    // printf("\n\n");
    // // Print frame
    // printf("Frame (%zu bytes):\n", frame_offset);
    // for (size_t i = 0; i < frame_offset; i++) {
    //     printf("%02x", frame[i]);
    //     if ((i + 1) % 4 == 0) printf(" ");
    // }
    // printf("\n\n");
    if (!to_server){
        int ret = aead_encrypt(keys->quic_key_server, sizeof(keys->quic_key_server),
        nonce, sizeof(nonce),
        header, hdr_offset,
        frame, frame_offset,
        encrypted_frame);
    } else {
        int ret = aead_encrypt(keys->quic_key, sizeof(keys->quic_key),
        nonce, sizeof(nonce),
        header, hdr_offset,
        frame, frame_offset,
        encrypted_frame);
    }
    // if (ret != 0) {
    //     printf("Encryption failed\n");
    //     free(encrypted_frame);
    //     return;
    // }
    // printf("Encrypted Frame (%d bytes): ", payload_length);
    // for (int i = 0; i < payload_length; i++) printf("%02x", encrypted_frame[i]);
    // printf("\n");

    // Header masking
    // combine the header and ecrypted frame
    uint8_t *crafted_packet = malloc(hdr_offset + payload_length);
    if (!crafted_packet) {
        printf("Memory allocation failed\n");
        free(encrypted_frame);
        return;
    }
    memcpy(crafted_packet, header, hdr_offset);
    /* payload_length includes the packet-number byte already in the header. */
    memcpy(&crafted_packet[hdr_offset], encrypted_frame, payload_length - 1);
    // printf("Crafted Packet (%d bytes): ", hdr_offset + payload_length);
    // for (int i = 0; i < hdr_offset + payload_length; i++) printf("%02x", crafted_packet[i]);
    // printf("\n");
    // Mask the header
    uint8_t *mask_hdr_test = malloc(hdr_offset);
    size_t out_size = 0;
    if(!to_server){
        header_mask(crafted_packet, hdr_offset + payload_length, hdr_offset, keys->quic_hp_server, &mask_hdr_test, &out_size);}
    else{
        header_mask(crafted_packet, hdr_offset + payload_length, hdr_offset, keys->quic_hp, &mask_hdr_test, &out_size);}
    // printf("Masked Header (%d bytes): ", hdr_offset);
    // for (int i = 0; i < hdr_offset; i++) printf("%02x", mask_hdr_test[i]);
    // printf("\n");

    // Build final packet
    memcpy(output, mask_hdr_test, hdr_offset);
    memcpy(&output[hdr_offset], encrypted_frame, payload_length - 1);
    *output_len = hdr_offset + payload_length -1;
    free(mask_hdr_test);
    free(crafted_packet);
    free(encrypted_frame);
    // printf("Final Packet (%d bytes): ", hdr_offset + payload_length -1);
    // for (int i = 0; i < hdr_offset + payload_length -1; i++) printf("%02x", output[i]);
    // printf("\n");

}


void quic_payload_crafter_tls(const uint8_t* scid, uint8_t scid_len,
    const uint8_t* dcid, uint8_t dcid_len,
    uint8_t* output, uint32_t* output_len, QuicCryptoKeys* keys, bool to_server) {
    uint8_t header[100];  // Sufficient space for QUIC connection close
    uint8_t frame[100]; // Sufficient space for QUIC Initial packet
    uint32_t hdr_offset = 0, frame_offset = 0;
    printf("=======================================QUIC Payload Crafter - to_server = %d ==================================\n", to_server);
    // Debug prints for connection IDs
    printf("DCID Length: %d\nDCID: ", dcid_len);
    for (int i = 0; i < dcid_len; i++) printf("%02x", dcid[i]);
    printf("\nSCID Length: %d\nSCID: ", scid_len);
    for (int i = 0; i < scid_len; i++) printf("%02x", scid[i]);
    printf("\n");


    // 1. First create the CONNECTION_CLOSE frame (transport error, type 0x1c)
    const char* reason = "BLOCKED BY POLICY SERVER";
    uint32_t reason_len = strlen(reason);
    uint32_t error_code = 0x0d; // INTERNAL_ERROR
    uint32_t frame_type = 0x06; // CRYPTO FRAME triggered the error

    // Frame type
    frame[frame_offset++] = 0x1d; // CONNECTION_CLOSE (transport error)

    // Error Code (variable-length integer)
    if (error_code < 64) {
        frame[frame_offset++] = error_code;
    } else if (error_code < 16384) {
        frame[frame_offset++] = 0x40 | (error_code >> 8);
        frame[frame_offset++] = error_code & 0xFF;
    } else {
        frame[frame_offset++] = 0x80 | (error_code >> 24);
        frame[frame_offset++] = (error_code >> 16) & 0xFF;
        frame[frame_offset++] = (error_code >> 8) & 0xFF;
        frame[frame_offset++] = error_code & 0xFF;
    }

    // // Frame Type that triggered error (variable-length integer)
    // if (frame_type < 64) {
    //     frame[frame_offset++] = frame_type;
    // } else if (frame_type < 16384) {
    //     frame[frame_offset++] = 0x40 | (frame_type >> 8);
    //     frame[frame_offset++] = frame_type & 0xFF;
    // } else {
    //     frame[frame_offset++] = 0x80 | (frame_type >> 24);
    //     frame[frame_offset++] = (frame_type >> 16) & 0xFF;
    //     frame[frame_offset++] = (frame_type >> 8) & 0xFF;
    //     frame[frame_offset++] = frame_type & 0xFF;
    // }

    // Reason Phrase Length (variable-length integer)
    if (reason_len < 64) {
        frame[frame_offset++] = reason_len;
    } else if (reason_len < 16384) {
        frame[frame_offset++] = 0x40 | (reason_len >> 8);
        frame[frame_offset++] = reason_len & 0xFF;
    } else {
        frame[frame_offset++] = 0x80 | (reason_len >> 24);
        frame[frame_offset++] = (reason_len >> 16) & 0xFF;
        frame[frame_offset++] = (reason_len >> 8) & 0xFF;
        frame[frame_offset++] = reason_len & 0xFF;
    }

    // Reason Phrase
    memcpy(&frame[frame_offset], reason, reason_len);
    frame_offset += reason_len;

    // 2. Now create the QUIC header
    header[hdr_offset++] = 0b11000000;  // Long header with Initial type

    // QUIC Version (4 bytes, big-endian)
    for (int i = 24; i >= 0; i -= 8) {
        header[hdr_offset++] = (QUIC_VERSION >> i) & 0xFF;
    }

    // Connection IDs
    if(!to_server){
        header[hdr_offset++] = scid_len;
        memcpy(&header[hdr_offset], scid, scid_len);
        hdr_offset += scid_len;

        uint8_t new_dcid []= {0xfd, 0x8b, 0x4b, 0xf2}; 
        printf("\nNew DCID size: %zu\n", sizeof(new_dcid));
        header[hdr_offset++] = sizeof(new_dcid);
        memcpy(&header[hdr_offset], new_dcid, sizeof(new_dcid));
        hdr_offset += sizeof(new_dcid);
    } else{
        header[hdr_offset++] = dcid_len;
        memcpy(&header[hdr_offset], dcid, dcid_len);
        hdr_offset += dcid_len;

        header[hdr_offset++] = scid_len;
        memcpy(&header[hdr_offset], scid, scid_len);
        hdr_offset += scid_len;
    }


    // Token Length (variable-length integer, zero in this case)
    header[hdr_offset++] = 0x00;  // Zero-length token (1-byte encoding)

    // Length Field (variable-length integer) - reserve max space (4 bytes)
    uint32_t hdr_length_offset = hdr_offset;
    hdr_offset += 4;  // Temporarily reserve maximum space

    // Packet number
    header[hdr_offset++] = 0x00;  // Packet number

    // Calculate total payload length (frame + AEAD overhead)
    uint32_t payload_length = frame_offset+16+1; // 16 bytes for AEAD tag
    uint32_t length_bytes_needed;

    // Encode payload length as variable-length integer
    if (payload_length < 64) {
        length_bytes_needed = 1;
        header[hdr_length_offset] = payload_length & 0x3F;
    } else if (payload_length < 16384) {
        length_bytes_needed = 2;
        header[hdr_length_offset] = 0x40 | ((payload_length >> 8) & 0x3F);
        header[hdr_length_offset + 1] = payload_length & 0xFF;
    } else {
        length_bytes_needed = 4;
        header[hdr_length_offset] = 0x80 | ((payload_length >> 24) & 0x3F);
        header[hdr_length_offset + 1] = (payload_length >> 16) & 0xFF;
        header[hdr_length_offset + 2] = (payload_length >> 8) & 0xFF;
        header[hdr_length_offset + 3] = payload_length & 0xFF;
    }

    // Shift header content if we used fewer bytes than reserved
    if (length_bytes_needed < 4) {
        uint32_t shift = 4 - length_bytes_needed;
        memmove(&header[hdr_length_offset + length_bytes_needed],
                &header[hdr_length_offset + 4],
                hdr_offset - (hdr_length_offset + 4));
        hdr_offset -= shift;
    }

    // Debug prints - C array format
    printf("uint8_t header[%d] = {", hdr_offset);
    for (int i = 0; i < hdr_offset; i++) {
        printf("0x%02x", header[i]);
        if (i < hdr_offset - 1) printf(", ");
    }
    printf("};\n");

    printf("uint8_t frame[%d] = {", frame_offset);
    for (int i = 0; i < frame_offset; i++) {
        printf("0x%02x", frame[i]);
        if (i < frame_offset - 1) printf(", ");
    }
    printf("};\n\n");
    
    uint8_t *encrypted_frame = malloc(payload_length-1);
    //NONCE GENERATION ==========================================================================================
    u_int8_t nonce[12];
    if (to_server){
        generate_aead_nonce(keys->quic_iv, sizeof(keys->quic_iv), pn(header,pn_length(header), hdr_offset), nonce);}
    else{
        generate_aead_nonce(keys->quic_iv_server, sizeof(keys->quic_iv_server), pn(header,pn_length(header), hdr_offset), nonce);}
    printf("===== AEAD Encryption Parameters =====\n");
    // Print server key
    printf("Server Key (%zu bytes):\n", sizeof(keys->quic_key_server));
    for (size_t i = 0; i < sizeof(keys->quic_key_server); i++) {
        printf("%02x", keys->quic_key_server[i]);
        if ((i + 1) % 16 == 0) printf("\n");
        else if ((i + 1) % 4 == 0) printf(" ");
    }
    printf("\n\n");
    
    // Print nonce
    printf("Nonce (%zu bytes):\n", sizeof(nonce));
    for (size_t i = 0; i < sizeof(nonce); i++) {
        printf("%02x", nonce[i]);
        if ((i + 1) % 4 == 0) printf(" ");
    }
    printf("\n\n");
    //print header
    printf("header (%zu bytes):\n", hdr_offset);
    for (size_t i = 0; i < hdr_offset; i++) {
        printf("%02x", header[i]);
        if ((i + 1) % 4 == 0) printf(" ");
    }
    printf("\n\n");
    // Print frame
    printf("Frame (%zu bytes):\n", frame_offset);
    for (size_t i = 0; i < frame_offset; i++) {
        printf("%02x", frame[i]);
        if ((i + 1) % 4 == 0) printf(" ");
    }
    printf("\n\n");
    if (!to_server){
        int ret = aead_encrypt(keys->quic_key_server, sizeof(keys->quic_key_server),
        nonce, sizeof(nonce),
        header, hdr_offset,
        frame, frame_offset,
        encrypted_frame);
    } else {
        int ret = aead_encrypt(keys->quic_key, sizeof(keys->quic_key),
        nonce, sizeof(nonce),
        header, hdr_offset,
        frame, frame_offset,
        encrypted_frame);
    }
    // if (ret != 0) {
    //     printf("Encryption failed\n");
    //     free(encrypted_frame);
    //     return;
    // }
    // printf("Encrypted Frame (%d bytes): ", payload_length);
    // for (int i = 0; i < payload_length; i++) printf("%02x", encrypted_frame[i]);
    // printf("\n");

    // Header masking
    // combine the header and ecrypted frame
    uint8_t *crafted_packet = malloc(hdr_offset + payload_length);
    if (!crafted_packet) {
        printf("Memory allocation failed\n");
        free(encrypted_frame);
        return;
    }
    memcpy(crafted_packet, header, hdr_offset);
    memcpy(&crafted_packet[hdr_offset], encrypted_frame, payload_length);
    // printf("Crafted Packet (%d bytes): ", hdr_offset + payload_length);
    // for (int i = 0; i < hdr_offset + payload_length; i++) printf("%02x", crafted_packet[i]);
    // printf("\n");
    // Mask the header
    uint8_t *mask_hdr_test = malloc(hdr_offset);
    size_t out_size = 0;
    if(!to_server){
        header_mask(crafted_packet, hdr_offset + payload_length, hdr_offset, keys->quic_hp_server, &mask_hdr_test, &out_size);}
    else{
        header_mask(crafted_packet, hdr_offset + payload_length, hdr_offset, keys->quic_hp, &mask_hdr_test, &out_size);}
    // printf("Masked Header (%d bytes): ", hdr_offset);
    // for (int i = 0; i < hdr_offset; i++) printf("%02x", mask_hdr_test[i]);
    // printf("\n");

    // Build final packet
    memcpy(output, mask_hdr_test, hdr_offset);
    memcpy(&output[hdr_offset], encrypted_frame, payload_length - 1);
    *output_len = hdr_offset + payload_length -1;
    // printf("Final Packet (%d bytes): ", hdr_offset + payload_length -1);
    // for (int i = 0; i < hdr_offset + payload_length -1; i++) printf("%02x", output[i]);
    // printf("\n");

}
